import React, { useState } from "react";
import { Form, FormGroup, Label, Input, Row, Col } from "reactstrap";
import "../Styles/PostJob.css";

const SECTORS = [
  "Private Company (Dhofar)",
  "Government / Ministry",
  "Small Business",
  "NGO / Non-profit",
];

const CATEGORIES = [
  "Design",
  "IT & Software",
  "Marketing",
  "Retail / Sales",
  "Logistics",
  "Administration",
  "Other",
];

const WORK_TYPES = ["Part-time", "One-time task", "Internship", "Contract"];
const RATE_TYPES = ["Per Hour", "Per Day", "Per Task"];
const PAYOUT_RULES = ["End of day", "Weekly", "On delivery", "Monthly"];
const EXPERIENCES = ["0–3", "1–2", "3–5", "5+"];
const DURATIONS = ["2 hour", "4 hour", "8 hour", "Multiple days"];

const PostJob = () => {
  // ----- form state
  const [jobTitle, setJobTitle] = useState("");
  const [organization, setOrganization] = useState("");
  const [sector, setSector] = useState(SECTORS[0]);
  const [category, setCategory] = useState(CATEGORIES[0]);
  const [workType, setWorkType] = useState(WORK_TYPES[0]);
  const [rate, setRate] = useState(5);
  const [rateType, setRateType] = useState(RATE_TYPES[0]);
  const [payout, setPayout] = useState(PAYOUT_RULES[0]);
  const [experience, setExperience] = useState(EXPERIENCES[0]);
  const [duration, setDuration] = useState(DURATIONS[1]);
  const [skills, setSkills] = useState("");
  const [description, setDescription] = useState("");
  const [training, setTraining] = useState(false); // checkbox (optional)

  // ----- submit (mock only)
  const handleSubmit = (e) => {
    e.preventDefault();
    const payload = {
      jobTitle,
      organization,
      sector,
      category,
      workType,
      rate,
      rateType,
      payout,
      experience,
      duration,
      skills,
      description,
      training,
    };
    console.log("Post Job payload:", payload);
    alert("Job posted (mock) ✅ — check console");
  };

  // ----- clear form
  const handleClear = () => {
    setJobTitle("");
    setOrganization("");
    setSector(SECTORS[0]);
    setCategory(CATEGORIES[0]);
    setWorkType(WORK_TYPES[0]);
    setRate(5);
    setRateType(RATE_TYPES[0]);
    setPayout(PAYOUT_RULES[0]);
    setExperience(EXPERIENCES[0]);
    setDuration(DURATIONS[1]);
    setSkills("");
    setDescription("");
    setTraining(false);
  };

  return (
    <section className="postjob-page">
      {/* Page title + subtitle */}
      <h1 className="page-title">
        Post a <span className="accent">Job</span>
      </h1>

      {/* Card */}
      <div className="postjob-card">
        <p className="page-sub">
          List a part-time or internship opportunity. Choose payout rules and
          mark if training is available.
        </p>
        <Form onSubmit={handleSubmit}>
          {/* Top row: Job Title + Organization */}
          <Row>
            <Col md={6}>
              <FormGroup>
                <Label>Job Title</Label>
                <Input
                  type="text"
                  placeholder="e.g., Reception Assistant"
                  value={jobTitle}
                  onChange={(e) => setJobTitle(e.target.value)}
                  required
                />
              </FormGroup>
            </Col>
            <Col md={6}>
              <FormGroup>
                <Label>Organization</Label>
                <Input
                  type="text"
                  placeholder="Your company/ ministry"
                  value={organization}
                  onChange={(e) => setOrganization(e.target.value)}
                  required
                />
              </FormGroup>
            </Col>
          </Row>

          {/* Sector + Category */}
          <Row>
            <Col md={6}>
              <FormGroup>
                <Label>Sector</Label>
                <Input
                  type="select"
                  value={sector}
                  onChange={(e) => setSector(e.target.value)}
                >
                  {SECTORS.map((s) => (
                    <option key={s}>{s}</option>
                  ))}
                </Input>
              </FormGroup>
            </Col>
            <Col md={6}>
              <FormGroup>
                <Label>Category</Label>
                <Input
                  type="select"
                  value={category}
                  onChange={(e) => setCategory(e.target.value)}
                >
                  {CATEGORIES.map((c) => (
                    <option key={c}>{c}</option>
                  ))}
                </Input>
              </FormGroup>
            </Col>
          </Row>

          {/* Work type + Rate + Rate type */}
          <Row>
            <Col md={4}>
              <FormGroup>
                <Label>Work Type</Label>
                <Input
                  type="select"
                  value={workType}
                  onChange={(e) => setWorkType(e.target.value)}
                >
                  {WORK_TYPES.map((w) => (
                    <option key={w}>{w}</option>
                  ))}
                </Input>
              </FormGroup>
            </Col>

            <Col md={4}>
              <FormGroup>
                <Label>Rate (OMR)</Label>
                <Input
                  type="number"
                  min="1"
                  step="0.5"
                  value={rate}
                  onChange={(e) => setRate(e.target.value)}
                />
              </FormGroup>
            </Col>

            <Col md={4}>
              <FormGroup>
                <Label>Rate Type</Label>
                <Input
                  type="select"
                  value={rateType}
                  onChange={(e) => setRateType(e.target.value)}
                >
                  {RATE_TYPES.map((t) => (
                    <option key={t}>{t}</option>
                  ))}
                </Input>
              </FormGroup>
            </Col>
          </Row>

          {/* Payout + Experience + Duration */}
          <Row>
            <Col md={4}>
              <FormGroup>
                <Label>Payout</Label>
                <Input
                  type="select"
                  value={payout}
                  onChange={(e) => setPayout(e.target.value)}
                >
                  {PAYOUT_RULES.map((p) => (
                    <option key={p}>{p}</option>
                  ))}
                </Input>
              </FormGroup>
            </Col>

            <Col md={4}>
              <FormGroup>
                <Label>Experience</Label>
                <Input
                  type="select"
                  value={experience}
                  onChange={(e) => setExperience(e.target.value)}
                >
                  {EXPERIENCES.map((x) => (
                    <option key={x}>{x}</option>
                  ))}
                </Input>
              </FormGroup>
            </Col>

            <Col md={4}>
              <FormGroup>
                <Label>Duration</Label>
                <Input
                  type="select"
                  value={duration}
                  onChange={(e) => setDuration(e.target.value)}
                >
                  {DURATIONS.map((d) => (
                    <option key={d}>{d}</option>
                  ))}
                </Input>
              </FormGroup>
            </Col>
          </Row>

          {/* Training checkbox */}
          <FormGroup check className="inline-check">
            <Input
              type="checkbox"
              checked={training}
              onChange={(e) => setTraining(e.target.checked)}
            />
            <Label check>Provide training for newcomers</Label>
          </FormGroup>

          {/* Skills */}
          <FormGroup className="mt-2">
            <Label>Skills</Label>
            <Input
              type="text"
              placeholder="Arabic, MS Office"
              value={skills}
              onChange={(e) => setSkills(e.target.value)}
            />
          </FormGroup>

          {/* Description */}
          <FormGroup>
            <Label>Description</Label>
            <Input
              type="textarea"
              rows="3"
              placeholder="Responsibilities, schedule, deliverables"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
            />
          </FormGroup>

          {/* Actions */}
          <div className="actions">
            <button type="submit" className="btn-primary">
              + Post Job
            </button>
            <button type="button" className="btn-ghost" onClick={handleClear}>
              Clear
            </button>
          </div>
        </Form>
      </div>
    </section>
  );
};

export default PostJob;
